const agreementNeutralHeadingRunes = "\ue000\ue001\ue002\ue003"

type agreementNeutralHeadingSource struct {
	Cut         agreementRemovedCommentDiagnosticReading
	Projected   string
	Positions   []int
	Plain, Page agreementMixedNamespaceReading
	Native      agreementNativeHeadingSource
	IDs         []string
	Valid       bool
}

func agreementNeutralHeadingRead(body string) agreementNeutralHeadingSource {
	r := agreementNeutralHeadingSource{Cut: agreementCommentCutP0Reading(body)}
	if !utf8.ValidString(body) {
		return r
	}
	source, positions := r.Cut.Projected, r.Cut.Positions
	if len(r.Cut.Check.Comments) == 0 {
		source = body
		positions = make([]int, len(body))
		for i := range positions {
			positions[i] = i
		}
	} else if !r.Cut.Valid {
		return r
	}
	if len(source) != len(positions) {
		return r
	}
	var projected strings.Builder
	for at, c := range source {
		size := utf8.RuneLen(c)
		if strings.ContainsRune(agreementNeutralHeadingRunes, c) {
			continue
		}
		if size < 1 || at+size > len(source) {
			return r
		}
		projected.WriteString(source[at : at+size])
		r.Positions = append(r.Positions, positions[at:at+size]...)
	}
	r.Projected = projected.String()
	for i, at := range r.Positions {
		if at < 0 || at >= len(body) || body[at] != r.Projected[i] || (i > 0 && at <= r.Positions[i-1]) {
			return r
		}
	}
	r.Plain = agreementMixedNamespaceRead(r.Projected, agreementFootnoteGrammar)
	r.Page = agreementMixedNamespaceRead(r.Projected, agreementExclusiveCodeGrammar)
	if !r.Plain.Eligible || !r.Page.Eligible || !cmp.Equal(r.Plain, r.Page) {
		return r
	}
	r.IDs = agreementProseNeutralAllocate(r.Page.Bases)
	r.Native = agreementNativeHeadingReading(body)
	if !slices.Equal(r.Native.Check.Targets, judge.LinkTargets(body)) {
		return r
	}
	r.Valid = true
	return r
}
func agreementProseNeutralAllocate(bases []string) []string {
	used := map[string]bool{}
	var ids []string
	for _, base := range bases {
		id := base
		for n := 2; used[id]; n++ {
			id = base + "-" + strconv.Itoa(n)
		}
		used[id] = true
		ids = append(ids, id)
	}
	return ids
}
func TestAgreementNeutralHeadingRuneDeclaration(t *testing.T) {
	doc, err := parser.ParseFile(token.NewFileSet(), "../render/wikilink.go", nil, 0)
	if err != nil {
		t.Fatal(err)
	}
	found := 0
	for _, decl := range doc.Decls {
		g, ok := decl.(*ast.GenDecl)
		if !ok || g.Tok != token.CONST {
			continue
		}
		for _, s := range g.Specs {
			v, ok := s.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for i, n := range v.Names {
				if n.Name != "inlinePlaceholderRunes" {
					continue
				}
				found++
				if i >= len(v.Values) {
					t.Fatal("declared placeholder value")
				}
				lit, ok := v.Values[i].(*ast.BasicLit)
				if !ok || lit.Kind != token.STRING {
					t.Fatal("declared placeholder literal")
				}
				value, err := strconv.Unquote(lit.Value)
				if err != nil || value != agreementNeutralHeadingRunes {
					t.Fatal("caught: whole declared placeholder rune set")
				}
			}
		}
	}
	if found != 1 {
		t.Fatal("caught: unique placeholder declaration")
	}
}

